package com.example.grpc.service;

import io.grpc.*;
import io.grpc.stub.StreamObserver;
import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.ConcurrentHashMap;
import java.nio.ByteBuffer;

public class SecureMessageService extends SecureMessageGrpc.SecureMessageImplBase {

    private static final int GCM_TAG_LENGTH = 128;
    private static final int GCM_IV_LENGTH = 12;
    private static final int CIRCUIT_BREAKER_THRESHOLD = 5;
    private static final long CIRCUIT_BREAKER_TIMEOUT_MS = 30000;

    private final SecretKeySpec masterKey;
    private final CircuitBreaker circuitBreaker;
    private final NonceManager nonceManager;

    public SecureMessageService(byte[] keyMaterial) {
        this.masterKey = new SecretKeySpec(keyMaterial, "AES");
        this.circuitBreaker = new CircuitBreaker(CIRCUIT_BREAKER_THRESHOLD, CIRCUIT_BREAKER_TIMEOUT_MS);
        this.nonceManager = new NonceManager();
    }

    @Override
    public void encryptAndForward(EncryptRequest request, StreamObserver<EncryptResponse> responseObserver) {
        if (circuitBreaker.isOpen()) {
            responseObserver.onError(Status.UNAVAILABLE
                .withDescription("Service temporarily unavailable")
                .asRuntimeException());
            return;
        }

        try {
            byte[] plaintext = request.getPayload().toByteArray();
            String channelId = request.getChannelId();

            EncryptionContext ctx = deriveEncryptionContext(channelId);
            byte[] ciphertext = performEncryption(plaintext, ctx);

            circuitBreaker.recordSuccess();
            EncryptResponse response = EncryptResponse.newBuilder()
                .setCiphertext(com.google.protobuf.ByteString.copyFrom(ciphertext))
                .setNonceId(ctx.getNonceId())
                .build();
            responseObserver.onNext(response);
            responseObserver.onCompleted();
        } catch (Exception e) {
            circuitBreaker.recordFailure();
            responseObserver.onError(Status.INTERNAL
                .withDescription("Encryption failed")
                .asRuntimeException());
        }
    }

    private EncryptionContext deriveEncryptionContext(String channelId) {
        byte[] iv = nonceManager.getNextNonce(channelId);
        long nonceId = nonceManager.getCurrentNonceId(channelId);
        return new EncryptionContext(masterKey, iv, nonceId);
    }

    private byte[] performEncryption(byte[] plaintext, EncryptionContext ctx) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LENGTH, ctx.getIv());
        cipher.init(Cipher.ENCRYPT_MODE, ctx.getKey(), spec);
        return cipher.doFinal(plaintext);
    }

    static class NonceManager {
        private final ConcurrentHashMap<String, NonceState> channelNonces = new ConcurrentHashMap<>();
        private final SecureRandom secureRandom = new SecureRandom();

        public byte[] getNextNonce(String channelId) {
            NonceState state = channelNonces.computeIfAbsent(channelId, k -> new NonceState(secureRandom));
            return state.nextNonce();
        }

        public long getCurrentNonceId(String channelId) {
            NonceState state = channelNonces.get(channelId);
            return state != null ? state.getCurrentId() : 0;
        }
    }

    static class NonceState {
        private final byte[] baseNonce;
        private final AtomicLong counter = new AtomicLong(0);
        private final SecureRandom random;

        NonceState(SecureRandom random) {
            this.random = random;
            this.baseNonce = new byte[GCM_IV_LENGTH];
            random.nextBytes(this.baseNonce);
        }

        public synchronized byte[] nextNonce() {
            long currentCount = counter.getAndIncrement();
            // Derive nonce from base + counter using XOR
            byte[] nonce = new byte[GCM_IV_LENGTH];
            System.arraycopy(baseNonce, 0, nonce, 0, GCM_IV_LENGTH);
            byte[] counterBytes = ByteBuffer.allocate(8).putLong(currentCount).array();
            // XOR counter into last 8 bytes of nonce
            for (int i = 0; i < 8; i++) {
                nonce[4 + i] ^= counterBytes[i];
            }
            return nonce;
        }

        public long getCurrentId() {
            return counter.get();
        }
    }

    static class CircuitBreaker {
        private final int threshold;
        private final long timeoutMs;
        private final AtomicInteger failureCount = new AtomicInteger(0);
        private volatile long lastFailureTime = 0;
        private volatile State state = State.CLOSED;

        enum State { CLOSED, OPEN, HALF_OPEN }

        CircuitBreaker(int threshold, long timeoutMs) {
            this.threshold = threshold;
            this.timeoutMs = timeoutMs;
        }

        public boolean isOpen() {
            if (state == State.OPEN) {
                if (System.currentTimeMillis() - lastFailureTime > timeoutMs) {
                    state = State.HALF_OPEN;
                    return false;
                }
                return true;
            }
            return false;
        }

        public void recordSuccess() {
            if (state == State.HALF_OPEN) {
                state = State.CLOSED;
                failureCount.set(0);
            }
        }

        public void recordFailure() {
            lastFailureTime = System.currentTimeMillis();
            if (failureCount.incrementAndGet() >= threshold) {
                state = State.OPEN;
            }
        }

        // Recovery method called when circuit breaker transitions from OPEN to HALF_OPEN
        public void onHalfOpen(String channelId, NonceManager nonceManager) {
            // Reset nonce state for the channel to ensure fresh cryptographic material
            // after recovery - but reuse existing NonceState to preserve counter continuity
            NonceState existing = nonceManager.channelNonces.get(channelId);
            if (existing != null) {
                existing.counter.set(0);
            }
        }
    }

    static class EncryptionContext {
        private final SecretKeySpec key;
        private final byte[] iv;
        private final long nonceId;

        EncryptionContext(SecretKeySpec key, byte[] iv, long nonceId) {
            this.key = key;
            this.iv = iv;
            this.nonceId = nonceId;
        }

        public SecretKeySpec getKey() { return key; }
        public byte[] getIv() { return iv; }
        public long getNonceId() { return nonceId; }
    }
}
